def transform_detection(
    sample: dict[str, Any],
    width: int,
    height: int,
    *,
    flip_horizontal: bool = False,
    crop: tuple[int, int, int, int] | None = None,
) -> dict[str, Any]:
    if (
        not isinstance(width, int)
        or isinstance(width, bool)
        or not isinstance(height, int)
        or isinstance(height, bool)
        or width <= 0
        or height <= 0
    ):
        raise ValueError("output dimensions must be positive integers")
    if not isinstance(sample, dict):
        raise ValueError("invalid sample")

    image = sample.get("image")
    annotations = sample.get("annotations")
    if not isinstance(image, list) or not image or not isinstance(annotations, list):
        raise ValueError("invalid sample")
    if not all(isinstance(row, list) and row for row in image):
        raise ValueError("invalid image")

    source_width = len(image[0])
    if any(len(row) != source_width for row in image):
        raise ValueError("image must be rectangular")
    source_height = len(image)

    if crop is None:
        left, top, right, bottom = 0, 0, source_width, source_height
    else:
        if not isinstance(crop, (list, tuple)) or len(crop) != 4:
            raise ValueError("crop must have four coordinates")
        if any(not isinstance(value, int) or isinstance(value, bool) for value in crop):
            raise ValueError("invalid crop")
        left, top, right, bottom = crop
        if not (0 <= left < right <= source_width and 0 <= top < bottom <= source_height):
            raise ValueError("invalid crop")

    validated_annotations: list[tuple[dict[str, Any], tuple[Real, Real, Real, Real]]] = []
    for annotation in annotations:
        if not isinstance(annotation, dict):
            raise ValueError("invalid annotation")
        box = annotation.get("bbox")
        if not isinstance(box, (list, tuple)) or len(box) != 4:
            raise ValueError("invalid bounding box")
        if any(not isinstance(value, Real) or isinstance(value, bool) for value in box):
            raise ValueError("invalid bounding box")
        x1, y1, x2, y2 = box
        if x1 > x2 or y1 > y2:
            raise ValueError("invalid bounding box")
        validated_annotations.append((annotation, (x1, y1, x2, y2)))

    crop_width = right - left
    crop_height = bottom - top
    cropped = [row[left:right] for row in image[top:bottom]]
    output_image = [
        [
            deepcopy(cropped[y * crop_height // height][x * crop_width // width])
            for x in range(width)
        ]
        for y in range(height)
    ]
    if flip_horizontal:
        output_image = [list(reversed(row)) for row in output_image]

    output_annotations: list[dict[str, Any]] = []
    for annotation, (x1, y1, x2, y2) in validated_annotations:
        ix1, iy1 = max(x1, left), max(y1, top)
        ix2, iy2 = min(x2, right), min(y2, bottom)
        if ix1 >= ix2 or iy1 >= iy2:
            continue

        new_box = [
            (ix1 - left) * width / crop_width,
            (iy1 - top) * height / crop_height,
            (ix2 - left) * width / crop_width,
            (iy2 - top) * height / crop_height,
        ]
        if flip_horizontal:
            new_box = [
                width - 1 - new_box[2],
                new_box[1],
                width - 1 - new_box[0],
                new_box[3],
            ]
        new_annotation = deepcopy(annotation)
        new_annotation["bbox"] = new_box
        output_annotations.append(new_annotation)

    result = deepcopy(sample)
    result["image"] = output_image
    result["annotations"] = output_annotations
    return result

